def transform(grid):
    """Shift every cell down one row; fill the new top row with background."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for color in row:
            counts[color] = counts.get(color, 0) + 1
    background = max(counts, key=counts.get)
    return [[background] * w] + [row[:] for row in grid[:-1]]

